def is_strobogrammatic(num):
    pairs = {'0': '0', '1': '1', '6': '9', '8': '8', '9': '6'}
    rotated = []
    for ch in num:
        if ch not in pairs:
            return False
        rotated.append(pairs[ch])
    rotated.reverse()                        # build the entire rotated string
    return ''.join(rotated) == num

