import java.util.*;

public class Main {
    static boolean isStrobogrammatic(String num) {
        Map<Character, Character> pairs = Map.of('0','0','1','1','6','9','8','8','9','6');
        StringBuilder rotated = new StringBuilder();
        for (char ch : num.toCharArray()) {
            if (!pairs.containsKey(ch)) return false;
            rotated.append(pairs.get(ch));
        }
        rotated.reverse();                         // build the entire rotated string
        return rotated.toString().equals(num);
    }
}

