import java.util.*;

public class Main {
    static boolean isStrobogrammatic(String num) {
        Map<Character, Character> pairs = Map.of('0','0','1','1','6','9','8','8','9','6');
        int l = 0, r = num.length() - 1;
        while (l <= r) {
            char left = num.charAt(l), right = num.charAt(r);
            if (!pairs.containsKey(left) || pairs.get(left) != right) return false;  // check the pairing
            l++; r--;
        }
        return true;
    }
}

